def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for dr, dc in ((1, 1), (1, -1)):
        seen = set()
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                # This is the first point of a maximal diagonal run.
                run=[]; rr,cc=r,c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr,cc)); seen.add((rr,cc)); rr+=dr; cc+=dc
                if len(run) < 2:
                    continue
                for (er,ec), (sr,sc) in ((run[0],(-dr,-dc)), (run[-1],(dr,dc))):
                    blocked=False
                    for ar,ac in ((er-1,ec),(er+1,ec),(er,ec-1),(er,ec+1)):
                        if 0 <= ar < h and 0 <= ac < w and grid[ar][ac] != bg:
                            blocked=True
                    if not blocked:
                        rr,cc=er+sr,ec+sc
                        while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                            out[rr][cc]=color; rr+=sr; cc+=sc
    return out

